function getKirasystemsTranslation(key, lang) {
    if (kirasystemsTranslations[lang] && kirasystemsTranslations[lang][key]) {
        return kirasystemsTranslations[lang][key];
    }
    if (kirasystemsTranslations.en && kirasystemsTranslations.en[key]) {
        return kirasystemsTranslations.en[key];
    }
    return null;
}

function applyKirasystemsTranslations(lang) {
    console.log('Applying kira-systems translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.kira-systems.')) {
            const translation = getKirasystemsTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} kira-systems translations`);
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyKirasystemsTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyKirasystemsTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyKirasystemsTranslations(currentLang);
}

